/**
 * Outline of Poland (Natural Earth 1:10m via world-atlas, public domain) projected with Web Mercator
 * into a 1000 × 940 box. `project` uses the same projection, so dealer pins land in the right place.
 */
export const POLAND_VIEWBOX = { width: 1000, height: 940 };

const SCALE = 5553.071373888044;
const TX = -1354.4739439144053;
const TY = 6392.3615586922515;

export function project(lat: number, lng: number): [number, number] {
  const rad = Math.PI / 180;
  return [TX + SCALE * lng * rad, TY - SCALE * Math.log(Math.tan(Math.PI / 4 + (lat * rad) / 2))];
}

